// Validate incoming email data
const { metadata, email, links, attachments } = $input.all();

// Validate required fields
if (!metadata || !email) {
  return { error: 'Missing required fields: metadata or email' };
}

if (!email.message_id || !email.sender || !email.recipient || !email.subject) {
  return { error: 'Missing required email fields' };
}

// Validate email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (typeof email.sender.email === 'string' && !emailRegex.test(email.sender.email)) {
  return { error: 'Invalid sender email format' };
}

if (!emailRegex.test(email.recipient)) {
  return { error: 'Invalid recipient email format' };
}

// Sanitize body to max 50KB
let body = email.body || '';
if (body.length > 51200) {
  body = body.substring(0, 51200);
}

// Trim whitespace
body = body.trim();
if (!body || body.length === 0) {
  return { error: 'Email body cannot be empty' };
}

// Return validated data
return {
  metadata: {
    request_id: metadata.request_id,
    timestamp: metadata.timestamp,
    extension_version: metadata.extension_version,
    user_email: metadata.user_email,
    analysis_started_at: new Date().toISOString()
  },
  email: {
    message_id: email.message_id,
    sender: email.sender,
    recipient: email.recipient,
    cc: email.cc || [],
    bcc: email.bcc || [],
    subject: (email.subject || '').substring(0, 500),
    body: body,
    body_html: email.body_html || null,
    timestamp: email.timestamp,
    headers: email.headers || {},
    is_reply: email.is_reply || false,
    is_forwarded: email.is_forwarded || false
  },
  links: (links || []).map(link => ({
    href: link.href,
    anchor_text: link.anchor_text || '',
    position: link.position || 0
  })),
  attachments: (attachments || []).map(att => ({
    name: att.name,
    size: att.size || 0,
    mime_type: att.mime_type || 'application/octet-stream'
  }))
};

// Sender & Domain Analysis Agent
const { email, metadata } = $input.all();
const sender = email.sender || {};
const senderDomain = sender.email?.split('@')[1] || '';
const headers = email.headers || {};

let score = 0;
const findings = [];

// Check domain age (dummy implementation - would use real WHOIS API)
const domainAge = Math.random() * 20; // years
if (domainAge < 0.5) {
  score += 15;
  findings.push({ type: 'new_domain', severity: 'high', evidence: `Domain registered only ${domainAge.toFixed(1)} years ago` });
} else if (domainAge < 2) {
  score += 8;
  findings.push({ type: 'young_domain', severity: 'medium', evidence: `Domain registered ${domainAge.toFixed(1)} years ago` });
}

// Check SPF status
const spfStatus = headers.spf || 'unknown';
if (spfStatus === 'fail') {
  score += 10;
  findings.push({ type: 'spf_fail', severity: 'high', evidence: 'SPF verification failed' });
} else if (spfStatus === 'pass') {
  score = Math.max(0, score - 2);
  findings.push({ type: 'spf_pass', severity: 'low', evidence: 'SPF verification passed' });
}

// Check DKIM status
const dkimStatus = headers.dkim || 'unknown';
if (dkimStatus === 'fail') {
  score += 10;
  findings.push({ type: 'dkim_fail', severity: 'high', evidence: 'DKIM verification failed' });
} else if (dkimStatus === 'pass') {
  score = Math.max(0, score - 2);
  findings.push({ type: 'dkim_pass', severity: 'low', evidence: 'DKIM verification passed' });
}

// Check DMARC status
const dmarcStatus = headers.dmarc || 'unknown';
if (dmarcStatus === 'fail') {
  score += 5;
  findings.push({ type: 'dmarc_fail', severity: 'medium', evidence: 'DMARC verification failed' });
}

// Check for domain mismatch
if (sender.email && sender.name) {
  const nameInEmail = sender.name.toLowerCase();
  const domainInEmail = sender.email.toLowerCase();
  if (nameInEmail.includes('@') && !nameInEmail.includes(senderDomain)) {
    score += 8;
    findings.push({ type: 'domain_mismatch', severity: 'high', evidence: `Sender name contains different domain: ${nameInEmail}` });
  }
}

// Cap at 25 points
score = Math.min(25, score);

return {
  agent_name: 'Sender Domain Analysis',
  score: score,
  findings: findings,
  details: {
    sender_domain: senderDomain,
    spf_status: spfStatus,
    dkim_status: dkimStatus,
    dmarc_status: dmarcStatus,
    sender_name: sender.name || 'Unknown',
    sender_email: sender.email || 'Unknown'
  }
};

// URL Intelligence Agent
const { email } = $input.all();
const links = $input.all().links || [];

let score = 0;
const findings = [];

const shortenerPatterns = [
  /bit\.ly/i, /tinyurl\.com/i, /ow\.ly/i, /goo\.gl/i,
  /short\.link/i, /url\.shortener/i, /bit/i
];

const dangerousExtensions = [
  '.exe', '.scr', '.vbs', '.com', '.bat', '.cmd', '.pif', '.lnk',
  '.msi', '.jar', '.zip', '.rar', '.7z'
];

// Check each link
links.forEach((link, index) => {
  const href = link.href || '';
  const anchorText = link.anchor_text || '';

  // Check for URL shorteners
  if (shortenerPatterns.some(pattern => pattern.test(href))) {
    score += 8;
    findings.push({
      type: 'url_shortener',
      severity: 'medium',
      position: index,
      evidence: `Shortened URL detected: ${href}`,
      url: href
    });
  }

  // Check for IP-based URLs
  if (/^http(s)?:\/\/(\d{1,3}\.){3}\d{1,3}/i.test(href)) {
    score += 10;
    findings.push({
      type: 'ip_based_url',
      severity: 'high',
      position: index,
      evidence: `IP-based URL detected: ${href}`,
      url: href
    });
  }

  // Check for URL-anchor text mismatch
  if (anchorText && anchorText.length > 0 && !href.includes(anchorText.split('.')[0])) {
    if (anchorText.length > 5 && !href.includes('example') && !href.includes('domain')) {
      score += 7;
      findings.push({
        type: 'url_mismatch',
        severity: 'medium',
        position: index,
        evidence: `URL mismatch - display text: "${anchorText}" actual URL: ${href}`,
        display_text: anchorText,
        actual_url: href
      });
    }
  }
});

// Check for suspicious TLDs
const suspiciousTLDs = ['.tk', '.ml', '.ga', '.cf', '.xyz', '.top', '.work'];
links.forEach((link, index) => {
  const href = link.href || '';
  if (suspiciousTLDs.some(tld => href.endsWith(tld))) {
    score += 5;
    findings.push({
      type: 'suspicious_tld',
      severity: 'medium',
      position: index,
      evidence: `Suspicious TLD detected in URL: ${href}`,
      url: href
    });
  }
});

// Cap at 25 points
score = Math.min(25, score);

return {
  agent_name: 'URL Intelligence',
  score: score,
  findings: findings,
  details: {
    total_links: links.length,
    suspicious_links: findings.filter(f => f.severity === 'high').length,
    analysis_timestamp: new Date().toISOString()
  }
};

// Parse LLM response
let response;
try {
  const responseText = $input.all().response || $input.all().text || '';
  // Try to extract JSON from response
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  response = JSON.parse(jsonMatch ? jsonMatch[0] : responseText);
} catch (e) {
  // Fallback response
  response = {
    score: 5,
    urgency_indicators: [],
    credential_harvest_risk: 'low',
    financial_scam_indicators: [],
    impersonation_risk: 'low',
    social_engineering_techniques: [],
    overall_assessment: 'Unable to parse LLM response, applying default low-risk assessment'
  };
}

const findings = [];

if (response.urgency_indicators && response.urgency_indicators.length > 0) {
  findings.push({
    type: 'urgency_language',
    severity: 'medium',
    evidence: `Urgency indicators found: ${response.urgency_indicators.join(', ')}`
  });
}

if (response.credential_harvest_risk === 'high') {
  findings.push({
    type: 'credential_harvest',
    severity: 'high',
    evidence: 'High risk of credential harvesting detected'
  });
}

if (response.financial_scam_indicators && response.financial_scam_indicators.length > 0) {
  findings.push({
    type: 'financial_scam',
    severity: 'high',
    evidence: `Financial scam indicators: ${response.financial_scam_indicators.join(', ')}`
  });
}

if (response.impersonation_risk === 'high') {
  findings.push({
    type: 'impersonation',
    severity: 'high',
    evidence: 'Impersonation attack detected'
  });
}

return {
  agent_name: 'Content Analysis',
  score: Math.min(25, response.score || 0),
  findings: findings,
  details: {
    credential_harvest_risk: response.credential_harvest_risk || 'low',
    impersonation_risk: response.impersonation_risk || 'low',
    social_engineering_techniques: response.social_engineering_techniques || [],
    overall_assessment: response.overall_assessment || ''
  }
};

// Header Analysis Agent (SPF/DKIM/DMARC)
const { email } = $input.all();
const headers = email.headers || {};

let score = 0;
const findings = [];

// SPF Check
const spfStatus = headers.spf || 'unknown';
if (spfStatus === 'fail' || spfStatus === 'softfail') {
  score += 5;
  findings.push({
    type: 'spf_failure',
    severity: 'medium',
    evidence: `SPF status: ${spfStatus}`
  });
}

// DKIM Check
const dkimStatus = headers.dkim || 'unknown';
if (dkimStatus === 'fail') {
  score += 3;
  findings.push({
    type: 'dkim_failure',
    severity: 'low',
    evidence: `DKIM status: ${dkimStatus}`
  });
}

// DMARC Check
const dmarcStatus = headers.dmarc || 'unknown';
if (dmarcStatus === 'fail' || dmarcStatus === 'quarantine') {
  score += 2;
  findings.push({
    type: 'dmarc_policy',
    severity: 'low',
    evidence: `DMARC status: ${dmarcStatus}`
  });
}

return {
  agent_name: 'Header Analysis',
  score: Math.min(10, score),
  findings: findings,
  details: {
    spf_status: spfStatus,
    dkim_status: dkimStatus,
    dmarc_status: dmarcStatus
  }
};

// Attachment Risk Agent
const { attachments } = $input.all();

let score = 0;
const findings = [];

const dangerousExtensions = [
  '.exe', '.scr', '.vbs', '.com', '.bat', '.cmd', '.pif', '.lnk',
  '.msi', '.jar', '.jar', '.app', '.deb', '.rpm'
];

const macroEnabledExtensions = ['.xls', '.xlsm', '.doc', '.docm', '.ppt', '.pptm'];

const suspiciousExtensions = [
  '.zip', '.rar', '.7z', '.iso', '.img', '.dmg'
];

attachments.forEach((attachment, index) => {
  const filename = attachment.name || '';
  const ext = filename.substring(filename.lastIndexOf('.')).toLowerCase();
  const size = attachment.size || 0;

  // Check dangerous extensions
  if (dangerousExtensions.includes(ext)) {
    score += 10;
    findings.push({
      type: 'dangerous_executable',
      severity: 'high',
      index: index,
      evidence: `Executable file detected: ${filename}`,
      filename: filename
    });
  }

  // Check macro-enabled Office files
  if (macroEnabledExtensions.includes(ext)) {
    score += 6;
    findings.push({
      type: 'macro_enabled_document',
      severity: 'high',
      index: index,
      evidence: `Macro-enabled document: ${filename}`,
      filename: filename
    });
  }

  // Check suspicious archives
  if (suspiciousExtensions.includes(ext)) {
    score += 4;
    findings.push({
      type: 'suspicious_archive',
      severity: 'medium',
      index: index,
      evidence: `Suspicious archive format: ${filename}`,
      filename: filename
    });
  }

  // Check large files
  if (size > 20971520) { // 20MB
    score += 2;
    findings.push({
      type: 'large_attachment',
      severity: 'low',
      index: index,
      evidence: `Large attachment (${(size / 1024 / 1024).toFixed(2)}MB): ${filename}`,
      filename: filename,
      size_mb: (size / 1024 / 1024).toFixed(2)
    });
  }
});

return {
  agent_name: 'Attachment Risk Analysis',
  score: Math.min(15, score),
  findings: findings,
  details: {
    total_attachments: attachments.length,
    dangerous_files: findings.filter(f => f.severity === 'high').length,
    analysis_timestamp: new Date().toISOString()
  }
};

// Risk Scoring Engine - Aggregate all agent scores
const agents = $input.all();

let agentResults = [];
if (Array.isArray(agents)) {
  agentResults = agents;
} else {
  agentResults = Object.values(agents).filter(item => item && item.agent_name);
}

// Extract scores from each agent
const senderRisk = agentResults.find(a => a.agent_name === 'Sender Domain Analysis')?.score || 0;
const contentRisk = agentResults.find(a => a.agent_name === 'Content Analysis')?.score || 0;
const urlRisk = agentResults.find(a => a.agent_name === 'URL Intelligence')?.score || 0;
const attachmentRisk = agentResults.find(a => a.agent_name === 'Attachment Risk Analysis')?.score || 0;
const authRisk = agentResults.find(a => a.agent_name === 'Header Analysis')?.score || 0;

// Calculate total risk score
const totalRiskScore = Math.min(
  100,
  senderRisk + contentRisk + urlRisk + attachmentRisk + authRisk
);

// Determine risk level
let riskLevel, color;
if (totalRiskScore <= 30) {
  riskLevel = 'SAFE';
  color = '#22c55e'; // Green
} else if (totalRiskScore <= 60) {
  riskLevel = 'SUSPICIOUS';
  color = '#eab308'; // Yellow
} else {
  riskLevel = 'HIGH_RISK';
  color = '#ef4444'; // Red
}

// Compile all findings
const allFindings = agentResults.reduce((acc, agent) => {
  if (agent.findings) {
    acc.push({
      agent: agent.agent_name,
      findings: agent.findings
    });
  }
  return acc;
}, []);

// Generate recommendations
const recommendations = [];

if (totalRiskScore > 60) {
  recommendations.push('⚠️ High risk detected - Do NOT click any links');
  recommendations.push('⚠️ Do NOT download or open attachments');
  recommendations.push('⚠️ Contact sender through trusted channel to verify');
  recommendations.push('⚠️ Consider reporting to IT security team');
} else if (totalRiskScore > 30) {
  recommendations.push('⚠️ Suspicious indicators detected');
  recommendations.push('⚠️ Verify sender identity before clicking links');
  recommendations.push('⚠️ Be cautious with attachments');
  recommendations.push('ℹ️ Check email headers for authentication issues');
} else {
  recommendations.push('✓ Email appears legitimate');
  recommendations.push('ℹ️ Standard security practices recommended');
}

// Add specific recommendations based on findings
if (allFindings.some(f => f.findings.some(x => x.type.includes('url')))) {
  recommendations.push('🔗 Hover over links to verify URLs before clicking');
}

if (allFindings.some(f => f.findings.some(x => x.type.includes('credential')))) {
  recommendations.push('🔐 Never enter passwords or sensitive data via email links');
}

return {
  risk_assessment: {
    risk_score: totalRiskScore,
    risk_level: riskLevel,
    color: color,
    summary: `This email has a ${riskLevel} risk score of ${totalRiskScore}/100`
  },
  breakdown: {
    sender_risk: senderRisk,
    content_risk: contentRisk,
    url_risk: urlRisk,
    attachment_risk: attachmentRisk,
    auth_risk: authRisk
  },
  detailed_findings: agentResults,
  all_findings: allFindings,
  recommendations: recommendations,
  actions_available: ['report_phishing', 'whitelist_sender', 'block_sender', 'delete_email'],
  analysis_complete: true,
  timestamp: new Date().toISOString()
};
